mapper.select:
SELECT COUNT(*)
FROM torn_stock_market_bar_15m
WHERE deleted = 0
  AND bar_start_time >= #{startInclusive}
  AND bar_start_time < #{endExclusive}
  AND build_version = #{buildVersion}

SELECT COUNT(*)
FROM torn_stock_market_bar_15m
WHERE deleted = 0
  AND bar_start_time >= #{startInclusive}
  AND bar_start_time < #{endExclusive}
  AND build_version = #{buildVersion}
  AND usable = true

SELECT COALESCE(quality_reason, 'UNKNOWN') AS name,
       COUNT(*)                            AS count
FROM torn_stock_market_bar_15m
WHERE deleted = 0
  AND bar_start_time >= #{startInclusive}
  AND bar_start_time < #{endExclusive}
  AND build_version = #{buildVersion}
  AND usable = false
GROUP BY quality_reason
ORDER BY count DESC

SELECT COUNT(*)
FROM torn_stock_strategy_feature_15m
WHERE deleted = 0
  AND bar_start_time >= #{startInclusive}
  AND bar_start_time < #{endExclusive}
  AND feature_version = #{featureVersion}

SELECT COUNT(*)
FROM torn_stock_market_bar_15m b
LEFT JOIN torn_stock_strategy_feature_15m f
       ON f.stocks_id = b.stocks_id
      AND f.bar_start_time = b.bar_start_time
      AND f.feature_version = #{featureVersion}
      AND f.deleted = 0
WHERE b.deleted = 0
  AND b.bar_start_time >= #{startInclusive}
  AND b.bar_start_time < #{endExclusive}
  AND b.build_version = #{buildVersion}
  AND b.usable = true
  AND f.id IS NULL

SELECT COUNT(*)
FROM torn_stock_strategy_feature_15m f
LEFT JOIN torn_stock_market_bar_15m b
       ON b.stocks_id = f.stocks_id
      AND b.bar_start_time = f.bar_start_time
      AND b.build_version = #{buildVersion}
      AND b.deleted = 0
WHERE f.deleted = 0
  AND f.bar_start_time >= #{startInclusive}
  AND f.bar_start_time < #{endExclusive}
  AND f.feature_version = #{featureVersion}
  AND b.id IS NULL

SELECT COUNT(*)
FROM torn_stock_strategy_feature_15m
WHERE deleted = 0
  AND bar_start_time >= #{startInclusive}
  AND bar_start_time < #{endExclusive}
  AND feature_version = #{featureVersion}
  AND strategy_ready = true

SELECT COALESCE(data_quality_reason, 'UNKNOWN') AS name,
       COUNT(*)                                 AS count
FROM torn_stock_strategy_feature_15m
WHERE deleted = 0
  AND bar_start_time >= #{startInclusive}
  AND bar_start_time < #{endExclusive}
  AND feature_version = #{featureVersion}
  AND strategy_ready = false
GROUP BY data_quality_reason
ORDER BY count DESC

SELECT COUNT(*)
FROM torn_stock_market_round
WHERE deleted = 0
  AND round_time >= #{startInclusive}
  AND round_time < #{endExclusive}
  AND (bar_build_version IS DISTINCT FROM #{buildVersion}
       OR feature_version IS DISTINCT FROM #{featureVersion})
